<?php
if($page==='biz-clients'):
function bizClientRow(array $c): void { ?>
<form method="post" class="biz-manage-row biz-client-row"><?=csrf()?><input type="hidden" name="id" value="<?=$c['id']?>"><input aria-label="이름" placeholder="이름" name="name" value="<?=e($c['name'])?>" maxlength="150" required><input aria-label="이메일" placeholder="이메일" name="email" type="email" value="<?=e($c['email'])?>" maxlength="150"><input aria-label="주소" placeholder="주소" name="address" value="<?=e($c['address'])?>" maxlength="500"><div class="biz-row-actions"><button name="action" value="biz_client" class="button <?=$c['id']?'secondary':'biz-add'?>"><?=$c['id']?'수정':'추가'?></button><?php if($c['id']&&!bizReferenced('client',(int)$c['id'])): ?><button name="action" value="biz_client_delete" formnovalidate class="button danger" data-confirm="이 거래처를 삭제할까요?">삭제</button><?php endif ?></div></form>
<?php } ?>
<section class="panel biz-compact"><?php foreach($clients as $c)bizClientRow($c); ?></section>
