<?php $seller=query('SELECT * FROM biz_settings WHERE id=1')->fetch(); ?>
<section class="panel biz-compact"><h2 class="biz-small-heading">인보이스 발신 정보</h2><form method="post" class="biz-seller-form"><?=csrf()?><input type="hidden" name="action" value="biz_settings"><?php foreach(['seller'=>'사업자명','email'=>'발신 이메일','gst'=>'GST/HST Registration No.','address'=>'주소'] as $key=>$label): ?><label><?=$label?><input name="<?=$key?>" value="<?=e($seller[$key])?>" type="<?=$key==='email'?'email':'text'?>" maxlength="<?=$key==='address'?500:150?>" required></label><?php endforeach ?><button class="button secondary">저장</button></form></section>
<?php elseif($page==='biz-products'):
function bizProductRow(array $p): void {$used=$p['id']&&bizReferenced('product',(int)$p['id']);$classificationLocked=$p['id']&&bizProductPosted((int)$p['id']); ?>
<form method="post" class="biz-manage-row biz-product-row"><?=csrf()?><input type="hidden" name="id" value="<?=$p['id']?>"><div><select aria-label="분류" name="category" data-biz-category <?=$classificationLocked?'disabled':''?>><?php foreach(bizCategories() as $key=>$label): ?><option value="<?=$key?>" <?=$p['category']===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select><?php if($classificationLocked): ?><input type="hidden" name="category" value="<?=e($p['category'])?>"><?php endif ?><span class="biz-etc-tax" <?=$p['category']!=='etc'?'hidden':''?>><select aria-label="Etc HST" name="hst_bp" <?=$classificationLocked?'disabled':''?>><option value="">HST 확인 필요</option><option value="0" <?=$p['hst_bp']!==null&&(int)$p['hst_bp']===0?'selected':''?>>HST 0%</option><option value="1300" <?=(int)$p['hst_bp']===1300?'selected':''?>>HST 13%</option></select><?php if($classificationLocked): ?><input type="hidden" name="hst_bp" value="<?=e((string)$p['hst_bp'])?>"><?php endif ?></span></div><div><input aria-label="한글 제품명" name="ko" placeholder="한글 제품명" value="<?=e($p['ko'])?>" maxlength="100" required></div><input aria-label="인보이스 제품명" name="en" placeholder="인보이스 제품명" value="<?=e($p['en'])?>" maxlength="100" required><input aria-label="정가" placeholder="정가" name="retail" type="number" min="0" max="999999.99" step=".01" value="<?=$p['retail_cents']===null?'':number_format($p['retail_cents']/100,2,'.','')?>"><div class="biz-row-actions"><button name="action" value="biz_product_save" class="button <?=$p['id']?'secondary':'biz-add'?>"><?=$p['id']?'수정':'추가'?></button><?php if($p['id']&&!$used): ?><button name="action" value="biz_product_delete" formnovalidate class="button danger" data-confirm="이 상품을 삭제할까요?">삭제</button><?php endif ?></div></form>
<?php } ?>
<div class="toolbar"><a class="button secondary" href="/?page=biz-prices">납품가 관리</a></div>
<section class="panel biz-compact"><div class="biz-manage-row biz-product-row biz-column-titles" aria-hidden="true"><span>분류</span><span>한글 제품명</span><span>인보이스 제품명</span><span>정가</span><span></span></div><?php foreach(bizCategories() as $key=>$label):$group=array_filter($products,fn($p)=>$p['category']===$key);if(!$group)continue; ?><h2 class="biz-category-heading"><?=$label?></h2><?php foreach($group as $p)bizProductRow($p);endforeach ?></section>
<section class="panel biz-compact"><h2 class="biz-small-heading">판매상품 추가</h2><?php bizProductRow(['id'=>0,'category'=>'kimchi','ko'=>'','en'=>'','pack'=>'','retail_cents'=>null,'hst_bp'=>0]); ?></section>
<?php elseif($page==='biz-prices'): $cid=(int)($_GET['client_id']??($clients[0]['id']??0));$client=null;foreach($clients as $c)if((int)$c['id']===$cid)$client=$c; ?>
<div class="toolbar"><a href="/?page=biz-products" class="button secondary">판매상품 관리</a></div><form method="get" class="biz-inline"><input type="hidden" name="page" value="biz-prices"><label>거래처<select name="client_id"><?php foreach($clients as $c): ?><option value="<?=$c['id']?>" <?=(int)$c['id']===$cid?'selected':''?>><?=e($c['name'])?></option><?php endforeach ?></select></label><button class="button secondary">보기</button></form>
<?php if($client): ?><p class="hint">OK Mart의 김치 외 상품과 개인 판매는 정가가 적용됩니다. 이곳의 납품가는 향후 거래에 적용됩니다.</p><?php foreach(bizCategories() as $key=>$label):$group=array_filter($products,fn($p)=>$p['category']===$key);if(!$group)continue; ?><section class="panel biz-compact biz-price-card" data-biz-price-card data-client="<?=$cid?>" data-category="<?=$key?>"><h2 class="biz-category-heading"><?=$label?></h2><div class="biz-manage-row biz-price-row biz-price-head"><span>제품명</span><span>정가</span><button type="button" class="biz-copy-price" data-biz-copy-all>일괄복사</button><span>납품가</span><button type="button" class="button biz-add" data-biz-add-all>일괄추가</button></div><?php foreach($group as $p):$price=$prices[$cid][$p['id']]??null; ?><form method="post" class="biz-manage-row biz-price-row" data-product="<?=$p['id']?>" data-unregistered="<?=$price===null?'1':'0'?>"><?=csrf()?><input type="hidden" name="client_id" value="<?=$cid?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><span><?=e(bizKo($p))?></span><span><?=$p['retail_cents']===null?'미등록':money((int)$p['retail_cents'])?></span><button type="button" class="biz-copy-price" data-biz-copy-price="<?=$p['retail_cents']===null?'':number_format($p['retail_cents']/100,2,'.','')?>" <?=$p['retail_cents']===null?'disabled':''?> aria-label="<?=e(bizKo($p))?> 정가 복사">→ 복사</button><input aria-label="<?=e(bizKo($p))?> 납품가" name="price" type="number" min="0" step=".01" max="999999.99" required value="<?=$price===null?'':number_format($price/100,2,'.','')?>"><div class="biz-row-actions"><button name="action" value="biz_price" class="button <?=$price===null?'biz-add':'secondary'?>"><?=$price===null?'추가':'수정'?></button><?php if($price!==null): ?><button name="action" value="biz_price_delete" formnovalidate class="button danger" data-confirm="이 납품가를 삭제할까요? 기존 거래 금액은 유지됩니다.">삭제</button><?php endif ?></div></form><?php endforeach ?></section><?php endforeach;endif;endif ?>
